import{_ as t,c as o,b as n,a2 as a}from"./chunks/framework.BEqfOpL-.js";const s="/images/podbean_connect_1_podseo.webp",r="/images/podbean_connect_2_form.webp",b=JSON.parse(`{"title":"Connect Podbean","description":"If your podcast is hosted on Podbean, you can bring its downloads into PodSEO. Podbean only lets you share your own statistics through an app that you register in your Podbean account, so the connection takes two keys: you create a small app on Podbean's developer site (a couple of minutes, free), then paste its Client ID and Client Secret into PodSEO. Once connected, your Podbean downloads appear in Analytics next to your other sources, per day and per episode, and refresh daily.","frontmatter":{},"headers":[],"relativePath":"features/podbean-connection.md","filePath":"features/podbean-connection.md"}`),d={name:"features/podbean-connection.md"};function i(h,e,p,l,c,u){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="connect-podbean" tabindex="-1">Connect Podbean <a class="header-anchor" href="#connect-podbean" aria-label="Permalink to &quot;Connect Podbean&quot;">​</a></h1><p>If your podcast is hosted on <strong>Podbean</strong>, you can bring its downloads into PodSEO. Podbean only lets you share your own statistics through an app that you register in your Podbean account, so the connection takes two keys: you create a small app on Podbean&#39;s developer site (a couple of minutes, free), then paste its <strong>Client ID</strong> and <strong>Client Secret</strong> into PodSEO. Once connected, your Podbean downloads appear in <strong>Analytics</strong> next to your other sources, per day and per episode, and refresh daily.</p><p>The connection is free on every plan, Podbean&#39;s and PodSEO&#39;s. In an organization, only <strong>Admins</strong> and <strong>Owners</strong> can connect a source in PodSEO; other team members can view the numbers.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>Use the Podbean account that hosts the show.</strong> The app you register can only read the podcasts of the account it belongs to. If your account holds several podcasts, one app covers all of them: PodSEO picks the one you are connecting.</li><li><strong>No coding is involved.</strong> &quot;App&quot; is just Podbean&#39;s name for a pair of keys. You don&#39;t need to build or install anything.</li><li><strong>Keep PodSEO open in another tab.</strong> You&#39;ll paste the two keys into the <strong>Podbean</strong> tab in <strong>Analytics</strong>.</li></ul><h2 id="step-1-open-the-podbean-tab-in-podseo" tabindex="-1">Step 1: Open the Podbean tab in PodSEO <a class="header-anchor" href="#step-1-open-the-podbean-tab-in-podseo" aria-label="Permalink to &quot;Step 1: Open the Podbean tab in PodSEO&quot;">​</a></h2><p>Choose your podcast, open <strong>Analytics</strong> and select the <strong>Podbean</strong> tab. The connection card shows two fields, <strong>Podbean Client ID</strong> and <strong>Podbean Client Secret</strong>, and the same steps as this guide.</p><p><a href="/images/podbean_connect_1_podseo.webp" title="Open screenshot at full size"><img src="'+s+'" alt="The Podbean connection card in PodSEO with the Client ID and Client Secret fields"></a></p><h2 id="step-2-register-an-app-on-podbean" tabindex="-1">Step 2: Register an app on Podbean <a class="header-anchor" href="#step-2-register-an-app-on-podbean" aria-label="Permalink to &quot;Step 2: Register an app on Podbean&quot;">​</a></h2><ol><li>Go to <a href="https://developers.podbean.com/" target="_blank" rel="noreferrer">developers.podbean.com</a> and click <strong>Register a new app</strong>.</li><li>Sign in with the Podbean account that hosts your show, if Podbean asks you to.</li></ol><p>Podbean opens the registration form.</p><h2 id="step-3-fill-in-the-form" tabindex="-1">Step 3: Fill in the form <a class="header-anchor" href="#step-3-fill-in-the-form" aria-label="Permalink to &quot;Step 3: Fill in the form&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Podbean field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Company Name</strong></td><td>Your name or your show&#39;s name</td></tr><tr><td><strong>Developer Contact Name</strong></td><td>Your name</td></tr><tr><td><strong>Contact Email</strong></td><td>Your email address</td></tr><tr><td><strong>App Name</strong></td><td><code>PodSEO</code> (any name works; this one helps you recognise it later)</td></tr><tr><td><strong>App logo</strong></td><td>Any square image, if Podbean asks for one</td></tr><tr><td><strong>Redirect URI (Development)</strong></td><td>Leave empty</td></tr><tr><td><strong>Redirect URI (Production)</strong></td><td>Leave empty</td></tr></tbody></table><p>Then click <strong>Submit</strong>.</p><p><a href="/images/podbean_connect_2_form.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Podbean&#39;s app form with PodSEO as the App Name and empty Redirect URIs"></a></p><p>The Redirect URIs are only needed by services that ask you to sign in through Podbean. PodSEO uses your keys directly, so leave them empty.</p><h2 id="step-4-copy-the-client-id-and-client-secret" tabindex="-1">Step 4: Copy the Client ID and Client Secret <a class="header-anchor" href="#step-4-copy-the-client-id-and-client-secret" aria-label="Permalink to &quot;Step 4: Copy the Client ID and Client Secret&quot;">​</a></h2><p>Back on <a href="https://developers.podbean.com/" target="_blank" rel="noreferrer">developers.podbean.com</a>, click <strong>Manage App</strong> next to the app you just created. Copy the <strong>Client ID</strong> and the <strong>Client Secret</strong>.</p><h2 id="step-5-paste-the-keys-into-podseo" tabindex="-1">Step 5: Paste the keys into PodSEO <a class="header-anchor" href="#step-5-paste-the-keys-into-podseo" aria-label="Permalink to &quot;Step 5: Paste the keys into PodSEO&quot;">​</a></h2><ol><li>In PodSEO&#39;s <strong>Podbean</strong> tab, paste the Client ID in <strong>Podbean Client ID</strong> and the Client Secret in <strong>Podbean Client Secret</strong>.</li><li>Click <strong>Connect Podbean</strong>.</li></ol><p>PodSEO checks the keys and finds your show among the podcasts of the account. Your downloads appear after the first import, usually within a few minutes, then update daily. See <a href="/features/hosting-analytics.html">Hosting platform reports</a> to read them.</p><h2 id="what-podseo-can-see" tabindex="-1">What PodSEO can see <a class="header-anchor" href="#what-podseo-can-see" aria-label="Permalink to &quot;What PodSEO can see&quot;">​</a></h2><p>Podbean shares daily downloads for the <strong>last 90 days</strong>. PodSEO imports those days when you connect, then keeps every day it collects from then on, so your history in PodSEO grows past 90 days over time. Episodes published more than 90 days before you connected show their downloads from the connection date onward.</p><p>Podbean&#39;s keys cannot be limited to reading: an app&#39;s keys could also edit your podcast. PodSEO stores them encrypted, only reads download statistics, and never publishes, edits or deletes anything on Podbean.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>The Podbean tab is missing.</strong> Check that you selected the right podcast. The tab appears for shows whose feed PodSEO recognises as hosted on Podbean.</p><p><strong>&quot;Podbean refused these keys.&quot;</strong> The Client ID or the Client Secret was copied incompletely, or belongs to another app. Open <strong>Manage App</strong> on developers.podbean.com and copy both again. Check for spaces at the start or end.</p><p><strong>&quot;This Podbean account hosts … not this podcast.&quot;</strong> The app belongs to a different Podbean account than the one that hosts the show. Sign in to Podbean with the account that hosts it, register an app there, and use its keys.</p><p><strong>PodSEO says Podbean no longer accepts the connection.</strong> This happens when the app was deleted on developers.podbean.com, or its keys changed. Copy the current keys (or register a new app) and paste them in the form shown on the <strong>Podbean</strong> tab. Numbers already shown keep their original dates.</p><p><strong>Still stuck?</strong> <a href="https://podseo.com/contact/" target="_blank" rel="noreferrer">Contact support</a> with your show&#39;s name. Never send your Client Secret or your Podbean password.</p><h2 id="how-to-disconnect" tabindex="-1">How to disconnect <a class="header-anchor" href="#how-to-disconnect" aria-label="Permalink to &quot;How to disconnect&quot;">​</a></h2><ol><li>In PodSEO, open <strong>Settings → Connections</strong>, expand <strong>Podbean</strong> for the correct show and choose <strong>Disconnect…</strong>. PodSEO stops reading your downloads and deletes the keys it stored. Your Podbean numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect.</li><li>To invalidate the keys themselves, delete the app on developers.podbean.com.</li></ol><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="/features/analytics-connections.html">Connect your analytics</a>: every source you can connect, and how to manage them</li><li><a href="/features/hosting-analytics.html">Hosting platform reports</a>: read your host&#39;s downloads, episodes and audience</li><li><a href="/features/analytics.html">Reading Analytics</a>: compare Podbean downloads with Apple, Spotify and YouTube</li></ul>',34)])])}const y=t(d,[["render",i]]);export{b as __pageData,y as default};
